local a={...}if#a<1 then error("printf: missing format")end;local b=table.remove(a,1)local c={}for d in b:gmatch"%%[%-%+ #0]?%d*%.?%d*[jzt]?[diuoxXfFeEgGaAcsq]"do local e=d:sub(-1,-1)local f=#c+1;local g=assert(a[f],"printf: missing argument for "..d)if e=="q"or e=="s"then c[f]=g else c[f]=assert(tonumber(g),"printf: argument "..g.." not a number")end end;print(b:format(table.unpack(c)))
